import {ToolRegistry} from './registry.js';

const weather = {
  name: 'weather',
  description: 'Get a forecast',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}, units: {type: 'string', enum: ['metric', 'imperial'], default: 'metric'}},
    required: ['location'],
  },
};

describe('tool input validation', () => {
  it('rejects invalid input and passes valid input through unchanged', async () => {
    const registry = new ToolRegistry();
    const calls: Record<string, unknown>[] = [];
    registry.register(weather, async input => {
      calls.push(input);
      return 'forecast';
    });
    const missing = await registry.execute('weather', {});
    const wrongType = await registry.execute('weather', {location: 74291});
    const wrongEnum = await registry.execute('weather', {location: 'Berlin', units: 'kelvin'});
    const valid = {location: 'Berlin', extra: 'retained'};
    const accepted = await registry.execute('weather', valid);
    expect({missing: missing.result, wrongType: wrongType.result, wrongEnum: wrongEnum.result, calls, accepted}).toEqual({
      missing: expect.stringMatching(/location.*required|required.*location/i),
      wrongType: expect.stringMatching(/location.*string|string.*location/i),
      wrongEnum: expect.stringMatching(/units.*(enum|allowed)|(enum|allowed).*units/i),
      calls: [valid],
      accepted: {result: 'forecast'},
    });
    expect(wrongType.result).not.toContain('74291');
  });

  it('rejects an invalid static schema when the tool is registered', () => {
    const registry = new ToolRegistry();
    expect(() => registry.register({...weather, inputSchema: {type: 'not-a-json-schema-type'}}, async () => 'ok')).toThrow(
      /weather/i
    );
  });

  it('validates each call against the current dynamic definition', async () => {
    const registry = new ToolRegistry();
    let required = 'location';
    const calls: Record<string, unknown>[] = [];
    registry.register(() => ({...weather, inputSchema: {...weather.inputSchema, required: [required]}}), async input => {
      calls.push(input);
      return 'forecast';
    });
    const first = await registry.execute('weather', {});
    required = 'units';
    const second = await registry.execute('weather', {location: 'Berlin'});
    expect({first: first.result, second: second.result, calls}).toEqual({
      first: expect.stringMatching(/location.*required|required.*location/i),
      second: expect.stringMatching(/units.*required|required.*units/i),
      calls: [],
    });
  });
});
EOF
cat > specs/hal-engine-tool-input-validation/spec.md <<'EOF'
# Tool Input Validation

| Field  | Value                  |
| ------ | ---------------------- |
| Issue  | re-cinq/HALEngine#37   |
| Status | Draft                  |

Tool input validation protects executors and gives the model actionable feedback when it sends malformed arguments.

- The registry rejects missing required fields, wrong types and invalid enum values with a ToolResponse identifying the property and constraint without exposing values; valid input, including extra properties, reaches the executor unchanged and without defaults or coercion. ([validated by: rejects invalid input and passes valid input through unchanged](../../src/orchestration/tools/registry.acceptance.test.ts#L15))
- Registering a static tool with an uncompilable schema throws an error naming the tool. ([validated by: rejects an invalid static schema when the tool is registered](../../src/orchestration/tools/registry.acceptance.test.ts#L38))
- A function-valued definition is validated against the schema resolved for each call. ([validated by: validates each call against the current dynamic definition](../../src/orchestration/tools/registry.acceptance.test.ts#L45))
EOF
